function beautifulNumbers(l, r) {
  // memo: "free positions,sum,product" -> beautiful ways to fill the free positions.
  const memo = new Map();
  const countUpTo = (limit) => {
    const digits = String(limit).split('').map(Number);
    const dfs = (pos, sum, product, tight, started) => {
      if (pos === digits.length) {
        return started && product % sum === 0 ? 1 : 0;
      }
      const key = `${digits.length - pos},${sum},${product}`;
      const reusable = started && !tight;
      if (reusable && memo.has(key)) {
        return memo.get(key);
      }
      const top = tight ? digits[pos] : 9;
      let count = 0;
      for (let d = 0; d <= top; d++) {
        if (started || d > 0) {
          count += dfs(pos + 1, sum + d, product * d, tight && d === top, true);
        } else {
          count += dfs(pos + 1, 0, 1, tight && d === top, false);
        }
      }
      if (reusable) {
        memo.set(key, count);
      }
      return count;
    };
    return dfs(0, 0, 1, true, false);
  };
  return countUpTo(r) - countUpTo(l - 1);
}

