function beautifulNumbers(l, r) {
  // Check every number in the range directly.
  let count = 0;
  for (let x = l; x <= r; x++) {
    let sum = 0;
    let product = 1;
    for (let rest = x; rest > 0; rest = Math.floor(rest / 10)) {
      sum += rest % 10;
      product *= rest % 10;
    }
    if (product % sum === 0) count++;
  }
  return count;
}

