function generate(rand, size) {
  if (size === 'large') {
    const l = 1 + Math.floor(rand() * (rand() < 0.5 ? 1000 : 999999999));
    return [l, l + Math.floor(rand() * (1e9 - l))];
  }
  // A short range starting anywhere from 1-digit to 9-digit numbers.
  const digits = 1 + Math.floor(rand() * 9);
  const l = 1 + Math.floor(rand() * (10 ** digits - 1));
  return [l, Math.min(999999999, l + Math.floor(rand() * 300))];
}
